class Solution {
  public int minCharacters(String a, String b) {
    int[] ca = new int[26], cb = new int[26];
    for (char ch : a.toCharArray()) ca[ch - 'a']++;
    for (char ch : b.toCharArray()) cb[ch - 'a']++;
    int ans = a.length() + b.length();
    for (int i = 0; i < 25; i++) {
      int aGreater = 0, bGreater = 0;
      for (int j = i + 1; j < 26; j++) {
        aGreater += ca[j];
        bGreater += cb[j];
      }
      ans = Math.min(ans, aGreater + (b.length() - bGreater));
      ans = Math.min(ans, bGreater + (a.length() - aGreater));
    }
    for (int i = 0; i < 26; i++) ans = Math.min(ans, a.length() + b.length() - ca[i] - cb[i]);
    return ans;
  }
}
